import sys
import re
import argparse
import unicodedata
import datetime
import glob

def normalize(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s) if unicodedata.category(c) != 'Mn')

def titlecase(s):
    def process_word(m):
        w = m.group(0)
        if w.isupper() or w.islower():
            return w.capitalize()
        return w
    return re.sub(r'[A-Za-z]+', process_word, s)

def german(s, naive=False):
    if not naive:
        if "Abenteuergruesse" in s: s = s.replace("Abenteuergruesse", "Abenteuergrüße")
        if "Koeffizienten" in s: pass 
        if "Bruecken" in s: s = s.replace("Bruecken", "Brücken")
    replacements = [
        ('ae', 'ä'), ('oe', 'ö'), ('ue', 'ü'), ('ss', 'ß'),
        ('Ae', 'Ä'), ('Oe', 'Ö'), ('Ue', 'Ü'), ('Ss', 'ẞ'),
        ('AE', 'Ä'), ('OE', 'Ö'), ('UE', 'Ü'), ('SS', 'ẞ')
    ]
    for old, new in replacements:
        s = s.replace(old, new)
    return s

def symbols(s, invert=False):
    sym_dict = {
        '!=': '≠', '->': '→', '=>': '⇒', '>=': '≥', '<=': '≤',
        '<->': '↔', '<-': '←', '<--': '⟵', '-->': '⟶', '==': '=='
    }
    if invert:
        sym_dict = {v: k for k, v in sym_dict.items() if k != v}
    for k in sorted(sym_dict.keys(), key=len, reverse=True):
        if k in sym_dict:
            s = s.replace(k, sym_dict[k])
    return s

def convert_replacement(r):
    r = re.sub(r'\$(\d+)', r'\\g<\1>', r)
    r = re.sub(r'\$([A-Za-z_][A-Za-z0-9_]*)', r'\\g<\1>', r)
    r = re.sub(r'\$\{([A-Za-z_][A-Za-z0-9_]*)\}', r'\\g<\1>', r)
    return r

def main():
    if "--" in sys.argv:
        idx = sys.argv.index("--")
        if len(sys.argv) > idx + 2:
            print("error: the argument '[REPLACEMENT]' cannot be used multiple times\n", file=sys.stderr)
            sys.exit(2)
        replacement_raw = sys.argv[idx+1]
        argv_to_parse = sys.argv[1:idx]
    else:
        replacement_raw = None
        argv_to_parse = sys.argv[1:]

    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("scope", nargs="?", default=".*")

    for flag in ["-u", "--upper", "-l", "--lower", "-t", "--titlecase", "-n", "--normalize",
                 "-g", "--german", "-S", "--symbols", "-d", "--delete", "-s", "--squeeze",
                 "-i", "--invert", "--dry-run", "--fail-no-files", "--fail-any", "--fail-none",
                 "-L", "--literal-string", "-j", "--join-language-scopes", "-H", "--hidden",
                 "--gitignored", "--sorted", "--german-prefer-original", "--german-naive"]:
        parser.add_argument(flag, action="store_true")

    for arg_flag in ["-G", "--glob", "--stdin-detection", "--stdout-detection", "--threads",
                     "--c", "--c-query", "--c-query-file", "--csharp", "--csharp-query", "--csharp-query-file",
                     "--go", "--go-query", "--go-query-file", "--hcl", "--hcl-query", "--hcl-query-file",
                     "--python", "--python-query", "--python-query-file", "--rust", "--rust-query", "--rust-query-file",
                     "--typescript", "--typescript-query", "--typescript-query-file", "--completions"]:
        parser.add_argument(arg_flag)

    parser.add_argument("-v", "--verbose", action="count", default=0)
    parser.add_argument("-h", "--help", action="store_true")
    parser.add_argument("-V", "--version", action="store_true")

    args, unknown = parser.parse_known_args(argv_to_parse)

    if args.help:
        print("Usage: executable [OPTIONS] [SCOPE] [-- <REPLACEMENT>]")
        sys.exit(0)
    if args.version:
        print("srgn 0.14.1")
        sys.exit(0)

    actions_count = args.upper + args.lower + args.titlecase + args.normalize + \
                    args.german + args.german_naive + args.symbols + args.delete + \
                    (replacement_raw is not None)

    if args.squeeze:
        now = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        sys.stderr.write(f"[{now} ERROR srgn] No actions specified, and not in search mode. Will return input unchanged, if any.\n")
    elif actions_count == 0 and not any([getattr(args, a) for a in ["c", "python", "rust", "go", "csharp", "hcl", "typescript"]]):
        now = datetime.datetime.now(datetime.timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        sys.stderr.write(f"[{now} ERROR srgn] No actions specified, and not in search mode. Will return input unchanged, if any.\n")

    scope_str = args.scope
    if args.literal_string:
        scope_str = re.escape(scope_str)

    try:
        scope_re = re.compile(scope_str)
    except Exception as e:
        print(f"error: invalid regex: {e}", file=sys.stderr)
        sys.exit(1)

