        if args.normalize: s = normalize(s)
        if args.upper: s = s.upper()
        if args.lower: s = s.lower()
        if args.titlecase: s = titlecase(s)
        if args.german or args.german_naive: s = german(s, args.german_naive)
        if args.symbols: s = symbols(s, args.invert)
        return s

