        if args.squeeze:
            out = ""
            last_end = 0
            consecutive_string = None
            consecutive_end = None
            for m in scope_re.finditer(text):
                if consecutive_string is not None and m.start() == consecutive_end:
                    consecutive_end = m.end()
                else:
                    if consecutive_string is not None:
                        out += consecutive_string
                        last_end = consecutive_end
                    out += text[last_end:m.start()]
                    consecutive_string = apply_actions(m.group(0))
                    consecutive_end = m.end()
            if consecutive_string is not None:
                out += consecutive_string
                out += text[consecutive_end:]
            else:
                out += text[last_end:]
            return out

        if args.delete:
            return scope_re.sub("", text)

        def repl(m):
            if replacement_template is not None:
                res = m.expand(replacement_template)
            else:
                res = m.group(0)
            return apply_actions(res)

        return scope_re.sub(repl, text)

    if args.glob:
        files = glob.glob(args.glob, recursive=True)
        if not files:
            if args.fail_no_files:
                print("Error: No files found", file=sys.stderr)
                sys.exit(1)
            sys.exit(0)

        for f in files:
            with open(f, 'r') as fp:
                content = fp.read()

            matched = bool(scope_re.search(content))
            if args.fail_any and matched:
                print("Error: Error applying: Some input was in scope", file=sys.stderr)
                sys.exit(1)
            if args.fail_none and not matched:
                print("Error: Error applying: No input was in scope", file=sys.stderr)
                sys.exit(1)

            new_content = process_text(content)

            if args.dry_run:
                lines = content.splitlines(True)
                if sys.stdout.isatty():
                    print(f"\033[35m{f}\033[0m")
                for i, line in enumerate(lines):
                    matches = list(scope_re.finditer(line))
                    if not matches: continue
                    offsets = ";".join([f"{m.start()}-{m.end()}" for m in matches])
                    mod_line = process_text(line)

                    if sys.stdout.isatty():
                        l_orig = line.rstrip('\n')
                        l_mod = mod_line.rstrip('\n')
                        sys.stdout.write(f"\033[32m{i+1}\033[0m:\033[1;31m{l_orig}\033[0m\n")
                        sys.stdout.write(f"\033[32m{i+1}\033[0m:\033[1;32m{l_mod}\033[0m\n")
                    else:
                        sys.stdout.write(f"{f}:{i+1}:{offsets}:{line}")
                        sys.stdout.write(f"{f}:{i+1}:{offsets}:{mod_line}")
            else:
                if content != new_content:
                    with open(f, 'w') as fp:
                        fp.write(new_content)
                print(f)
    else:
        content = sys.stdin.read()
        matched = bool(scope_re.search(content))
        if args.fail_any and matched:
            print("Error: Error applying: Some input was in scope", file=sys.stderr)
            sys.exit(1)
        if args.fail_none and not matched:
            print("Error: Error applying: No input was in scope", file=sys.stderr)
            sys.exit(1)

        new_content = process_text(content)
        sys.stdout.write(new_content)

if __name__ == "__main__":
    main()
